#!/usr/bin/env node
// Generates packages/rules/src/bundled-rules.ts from the YAML files in
// packages/rules/rules/**.
//
// Why: For Bun --compile to produce a self-contained binary, the rule pack
// content must be embedded at build time — there is no node_modules or
// filesystem to read YAML from at runtime inside the /$bunfs/ virtual FS.
//
// What this generates: an array of pre-parsed rule documents (already JSON-
// parsed from YAML), so neither js-yaml nor fs.readFile run at runtime in
// the compiled binary path. The Node + npm path can still use --rules-dir
// or the on-disk YAMLs (load-rules.ts decides at runtime).
//
// Run via: `prepare` script (after pnpm install) AND `prepack` (before npm
// publish) AND in CI before `bun build --compile`. Idempotent — overwrites
// only if content changes.

import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { load as parseYaml } from "js-yaml";

const __dirname = dirname(fileURLToPath(import.meta.url));
const RULES_ROOT = join(__dirname, "..");
const YAML_ROOT = join(RULES_ROOT, "rules");
const BUNDLE_PATH = join(RULES_ROOT, "src", "bundled-rules.ts");

function findYamlFiles(dir) {
  const out = [];
  for (const entry of readdirSync(dir)) {
    const abs = join(dir, entry);
    const st = statSync(abs);
    if (st.isDirectory()) {
      out.push(...findYamlFiles(abs));
    } else if (entry.endsWith(".yaml") || entry.endsWith(".yml")) {
      out.push(abs);
    }
  }
  return out;
}

const yamlFiles = findYamlFiles(YAML_ROOT).sort();
const documents = yamlFiles.map((f) => ({
  source: relative(RULES_ROOT, f).replace(/\\/g, "/"),
  doc: parseYaml(readFileSync(f, "utf-8")),
}));

const banner =
  "// Generated by scripts/sync-bundle.mjs — do NOT edit by hand.\n" +
  "// Source of truth: packages/rules/rules/**/*.yaml.\n" +
  "// Regenerated on every install/pack/CI; bakes parsed rule content into the\n" +
  "// compiled binary so Bun --compile output is self-contained (no fs reads).\n";

const body =
  "export interface BundledRuleDocument {\n" +
  "  readonly source: string;\n" +
  "  readonly doc: unknown;\n" +
  "}\n\n" +
  "export const BUNDLED_RULE_DOCUMENTS: ReadonlyArray<BundledRuleDocument> =\n  " +
  JSON.stringify(documents, null, 2) +
  ";\n";

const next = banner + body;

let current = "";
try {
  current = readFileSync(BUNDLE_PATH, "utf-8");
} catch {
  // First run.
}

if (current !== next) {
  writeFileSync(BUNDLE_PATH, next);
}
// Silent on success.
